import SwiftUI
import AtiCleanerCore
struct MemoryView:View{@State private var snap=MemoryService.snapshot();var body:some View{VStack(alignment:.leading,spacing:22){PageHeader(icon:"memorychip",title:"Bellek",subtitle:"Anlık bellek kullanımını ve sıkıştırılmış belleği görüntüleyin.",tint:Theme.memory);if let s=snap{HStack{ReadyRing(icon:"memorychip.fill",title:"Bellek",detail:"\(Int(s.used*100/max(s.total,1)))% kullanım",tint:Theme.memory);VStack(alignment:.leading,spacing:12){Text("Toplam: \(Int64(s.total).formattedBytes)");Text("Kullanılan: \(Int64(s.used).formattedBytes)");Text("Boş: \(Int64(s.free).formattedBytes)");Text("Sıkıştırılmış: \(Int64(s.compressed).formattedBytes)")}.font(.title3)}}else{Text("Bellek bilgisi okunamadı")};Spacer()}.padding(24).task{snap=MemoryService.snapshot()}}}
